insert into public.products (id, name, category, size, description, usage, caution, price, in_stock, image_url, image_credit, image_position, sort_order) values
  ('liquid-detergent-2l', 'Liquid Laundry Detergent', 'Detergents', '2 litres', 'Everyday liquid detergent for machine and hand washing of washable fabrics.', 'Use one cap per normal load. Pre-treat heavy stains with a little neat liquid.', 'Keep out of reach of children. Avoid contact with eyes.', 6500, true, '/images/products/liquid-detergent.jpg', 'Sufyan', null, 0),
  ('powder-detergent-1kg', 'Powder Detergent', 'Detergents', '1 kg', 'Concentrated washing powder for whites and colourfast items.', 'Dissolve two scoops in water before adding garments.', 'Keep dry and sealed. Keep out of reach of children.', 3200, true, '/images/products/powder-detergent.jpg', 'HowToGym', null, 1),
  ('fabric-softener-1l', 'Fabric Softener', 'Fabric care', '1 litre', 'Leaves washed garments soft and easier to iron.', 'Add one cap to the final rinse. Do not pour directly onto fabric.', null, 4000, true, '/images/products/fabric-softener-pour.jpg', 'No Revisions', null, 2),
  ('stain-remover-500ml', 'Stain Remover Spray', 'Fabric care', '500 ml', 'Pre-wash spray for common food, grease and collar stains.', 'Test on a hidden area first. Spray, leave for 5 minutes, then wash as normal.', 'Not suitable for silk, wool or leather.', 3800, false, '/images/products/stain-remover.jpg', 'Brett Jordan', null, 3),
  ('starch-spray-400ml', 'Ironing Starch Spray', 'Fabric care', '400 ml', 'Gives shirts, native wear and linens a crisp, neat finish.', 'Shake well and spray lightly from 20 cm before ironing.', 'Pressurised container. Keep away from heat.', 2500, true, '/images/products/starch-spray.jpg', 'Annie Spratt', null, 4),
  ('surface-disinfectant-1l', 'Multi-surface Disinfectant', 'Disinfectants', '1 litre', 'For cleaning hard surfaces in homes, offices and shared spaces.', 'Dilute as directed on the label. Wipe and allow to air dry.', 'Do not mix with other cleaning products. Store in a cool place.', 4500, true, '/images/products/surface-disinfectant.jpg', 'Towfiqu barbhuiya', null, 5),
  ('microfibre-cloths-5', 'Microfibre Cleaning Cloths', 'Cleaning tools', 'Pack of 5', 'Reusable, lint-free cloths for dusting, glass and surfaces.', 'Use damp or dry. Machine washable; avoid fabric softener.', null, 3000, true, '/images/products/microfibre-cloths.jpg', 'GoGoNano', null, 6),
  ('rubber-gloves', 'Household Rubber Gloves', 'Protective accessories', '1 pair · medium', 'Protect hands while cleaning or handling detergents.', 'Rinse and dry inside out after use.', null, 1500, true, '/images/products/rubber-gloves.jpg', 'Karolina Kołodziejczak', null, 7)
insert into public.services (id, icon, name, category, summary, includes, note, image_url, image_credit, image_position, sort_order) values
  ('laundry', 'laundry', 'Laundry', 'Garment care', 'Everyday and household washable items, cleaned and neatly finished.', array['Sorting', 'Washing', 'Finishing & ironing', 'Folding & packaging']::text[], 'Wash-and-fold and wash-and-iron options are quoted according to availability.', '/images/photos/folded-laundry.jpg', 'Dan LeFebvre', null, 0),
  ('cleaning', 'cleaning', 'Wet & Dry Cleaning', 'Garment care', 'Professional care for suitable garments, textiles and delicate items.', array['Label & fabric assessment', 'Wet or dry cleaning programme', 'Careful finishing', 'Final quality check']::text[], 'Not every fabric or stain suits every process — we explain any limitations before work begins.', '/images/photos/garments-rail.jpg', 'Parker Burchfield', null, 1),
  ('tailor', 'tailor', 'Tailor Repairs & Alterations', 'Garment care', 'Repairs and fit adjustments that give your favourite items more life.', array['Hemming', 'Fit adjustments', 'Repairs', 'Button & zip replacement']::text[], 'We confirm the item''s condition, measurements, scope and completion date before work.', '/images/photos/tailor-at-work.jpg', 'Ali Mkumbwa', null, 2),
  ('shoe', 'shoe', 'Shoe Repair / Cobbler', 'Garment care', 'Care, selected repairs and restoration for appropriate footwear.', array['Cleaning', 'Sole repairs', 'Stitching', 'Restoration']::text[], 'Availability depends on the material and condition of each pair; you''ll get an agreed quote first.', '/images/services/shoe-repair.jpg', 'Zheng Yijun', null, 3),
  ('upholstery', 'upholstery', 'Upholstery & Rug Cleaning', 'Home care', 'Cleaning for selected sofas, chairs, rugs and other suitable furnishings.', array['Inspection & fabric identification', 'Suitability test', 'Cleaning', 'Drying checks']::text[], 'We test suitability first and don''t promise every stain will come out.', '/images/services/upholstery.jpg', 'Giorgio Trovato', null, 4),
  ('janitorial', 'janitorial', 'Janitorial Services', 'Home care', 'Routine and one-off cleaning for offices, shops, schools and residential spaces.', array['Site walkthrough', 'Agreed cleaning schedule', 'Floors, surfaces & washrooms', 'Supervised quality checks']::text[], 'Scope, frequency and price are agreed after a site visit; cleaning products and equipment are confirmed in the quote.', '/images/photos/detergent-bubbles.jpg', 'Julia Ly', null, 5),
  ('pest', 'pest', 'Pest Control', 'Home care', 'Assessment-led pest management for homes and commercial premises.', array['Site inspection', 'Preparation advice', 'Treatment', 'Follow-up visit']::text[], 'Carried out by qualified personnel following safety procedures. Results vary by site — we don''t guarantee eradication.', '/images/services/pest-control.jpg', 'MESTO Sprayers', null, 6)
